const r = await tools.create_goal({
 objective: "从人群角度挖掘商机：逐个分析宝妈、上班族、大学生、小老板/个体户、老年人、新手父母等人群的日常工作与生活圈子（具体活动、重复劳动、现有工具的缺口），找出其中适合软件开发者变现的低竞争机会。要求：每个机会标明服务哪类人群、他们在什么场景下遇到什么问题、现在怎么解决的（痛点）、竞争程度、稳定/不稳定、具体第一步做什么、大概能收多少钱。深挖到别人看不到的信息差层面。",
});
console.log(JSON.stringify(r.goal, null, 1));
